import json,csv,collections,statistics,re
from pathlib import Path
P=Path('apps/pfotentechnik/reports/indexation-gap-analysis-35.5');f=json.loads((P/'feature-matrix.json').read_text());stats=json.loads((P/'group-statistics.json').read_text());g=['indexed','crawled-not-indexed','discovered-not-indexed'];labels=['Indexiert (90)','Gecrawlt, nicht indexiert (91)','Gefunden, nicht indexiert (78)']
def fmt(v):return '–' if v is None else str(round(v,3)).replace('.',',')
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows])
text=['# 35.5 – Indexation Gap Analysis','', '**Ergebnis:** Das deutlichste gemessene Muster betrifft die jüngeren, nur gefundenen Seiten. Für bereits gecrawlte Seiten ergibt sich keine belastbare einfache Trennregel aus Textlänge, Quellenzahl, Wiederholung oder Klicktiefe. Konkrete Quellen-/Entscheidungsprobleme existieren, aber auch indexierte Seiten enthalten vergleichbare Schwächen. Die zehn Überarbeitungen sind deshalb ein begrenztes Experiment, keine diagnostizierte siteweite Qualitätsreparatur.','', '## Datenbasis und Zeitbezug','', '259 aktuelle Canonicals; exakte GSC-Zuordnung aus 35.4 unverändert: 90 / 91 / 78. Export vom 02.11.2026, Coverage-Diagramm bis 23.10., einzelne Crawldaten bis 24.10. Keine Live-Indexabfrage. Der untersuchte Ausgangsinhalt ist Commit `fda89099` einschließlich 35.4/35.3B; Merkmalsbaseline und Git-Alter beziehen sich auf den 02.11.2026. Fertigstellung der Vorbereitung am 03.11.2026. HTTP-Kontrollen aus 35.3 werden mit ihrem ursprünglichen Prüfzeitpunkt wiederverwendet.','', 'Wichtig: Das jüngste Exporturteil ist älter als die 35.4-Texte. Der Vergleich ist kein Nachweis einer Bewertung dieser Texte durch Google. 23 der indexierten, zwölf der gecrawlten und sechs der gefundenen Canonicals wurden durch 35.4 verändert. Sensitivitätsauswertung ohne diese 41 steht in `group-statistics.json`. Git-Existenz wird nicht als Veröffentlichungsdatum ausgegeben; zusätzliche publizierte Metadaten sind als unbestätigt gekennzeichnet.','', '## Zuerst Seitentyp und Themencluster trennen','']
rows=[]
for typ in ['product','guide','comparison','manufacturer','category','other']:
 d=[r for r in f if r['page_type']==typ];rows.append([typ,len(d)]+[str(sum(r['gsc_status']==z for r in d))+' ('+fmt(100*sum(r['gsc_status']==z for r in d)/len(d))+' %)' for z in g])
text += [table(['Typ','Gesamt','Indexiert','Gecrawlt','Gefunden'],rows),'','Elf Toilettenprodukte und acht Kameraprodukte stehen vollständig auf „Gefunden“; bei Katzenklappenprodukten sind neun gefunden und eines gecrawlt. In diesen Zellen fehlt eine indexierte Produkt-Kontrollgruppe. Man darf ihre Eigenschaften nicht mit den überwiegend älteren Futterautomaten gleichsetzen.','', '### Gleicher Typ und ähnlicher Cluster','']
rows=[]
for s in ['type-cluster:product:futterautomaten','type-cluster:product:trinkbrunnen','type-cluster:guide:futterautomaten','type-cluster:guide:trinkbrunnen']:
 for z in g:
  d=stats[s][z]
  if d['n']:rows.append([s.removeprefix('type-cluster:'),z,d['n']]+[fmt(d['metrics'][m]['median']) for m in ['git_age_days','visible_main_words','documented_source_links','incoming_contextual_sources','max_related_tfidf_cosine']])
text += [table(['Typ/Cluster','Status','n','Git-Alter, Tage','Hauptinhalt, Wörter','Quellenlinks*','Kontext-Inlinks','Ähnlichkeit*'],rows),'', '*Mediane. Quellenlinks sind strukturell erfasste sichtbare externe Belegkandidaten, keine bewertete Quellenqualität; zusätzliche Feldquellen stehen separat in der Matrix. Ähnlichkeit ist bereinigter lexikalischer TF-IDF-Kosinus, keine Qualitätsnote und kein Beweis gleicher Suchintention. Zellen unter zehn sind klein; insbesondere drei gefundene Futterautomaten-/Trinkbrunnenprodukte erlauben keine verlässliche Verallgemeinerung.','', 'Bei Futterautomatenprodukten liegen indexierte und gecrawlte Seiten praktisch gleich: 1.033 gegen 1.046 Wörter, je 113 Git-Tage, je zwei Quellenlinks und je ein kontextueller Inlink im Median. Die ähnliche Quellenzahl schließt konkrete Fehlzuordnungen oder unpassende Belege nicht aus.','', 'Bei Ratgebern bleibt der Längenunterschied auch innerhalb der Cluster: Futterautomaten 1.191,5 gegen 3.100,5 Wörter, Trinkbrunnen 875,5 gegen 1.343,5. Mehr Inhalt oder mehr Quellen allein sind damit kein begründeter Recovery-Hebel. Bei Trinkbrunnenratgebern haben negative Seiten weniger Kontext-Inlinks, bei Futterautomatenratgebern sind die Mediane gleich. Keine einheitliche Verlinkungserklärung.','', '## Gesamtvergleich: beschreibende Merkmale','']
metrics={'git_age_days':'Erste Git-Existenz, Tage bis Baseline','visible_main_words':'Wörter im sichtbaren Hauptinhalt','recurrent_12token_fraction':'Anteil wiederkehrender 12-Token-Spannen','max_related_tfidf_cosine':'Ähnlichkeit zum Typ-/Clusternachbarn','documented_source_links':'Sichtbare Quellenlink-Kandidaten','independent_primary_source_candidates':'Unabhängige Quellen-Domainkandidaten','incoming_contextual_sources':'Eingehende kontextuelle Quellseiten','incoming_contextual_indexed':'Davon im Export indexierte Quellseiten','home_click_depth':'Klicktiefe ab Startseite'}
text += [table(['Merkmal']+labels,[[label]+[fmt(stats['all'][z]['metrics'][m]['median']) for z in g] for m,label in metrics.items()]),'', '„Gefunden“: Median 88 statt 112 Git-Tage, also 24 Tage beziehungsweise 21,4 % jünger. 65/78 dieser Seiten sind erst nach dem 27.07. im Git belegt. In A und B sind dagegen 88/90 beziehungsweise 90/91 bis dahin belegt. Das passt zu unterschiedlicher Discovery-/Verarbeitungshistorie; es beweist weder eine Alterswirkung noch, dass Google nie später gecrawlt hat.','', 'Keinen strukturell erfassten Kontextlink aus einer im Export indexierten Seite haben 26/90 indexierte Seiten (28,9 %), 30/91 gecrawlte (33,0 %) und 41/78 gefundene (52,6 %). Gegenüber A liegt C um 23,7 Prozentpunkte höher, ungefähr Faktor 1,82. Das kann mit Seitentyp, Themenalter und der historischen Auswahl indexierter Quellen zusammenhängen; Linkrichtung ist hier nicht Ursache/Wirkungsrichtung.','', '### Effektgrößen und Unsicherheit','']
effects=list(csv.DictReader((P/'exploratory-effect-sizes.csv').open()));sel=[]
for e in effects:
 if e['stratum']=='all' and e['feature'] in ['git_age_days','visible_main_words','recurrent_12token_fraction','incoming_contextual_indexed']:sel.append([e['comparison'].replace(' minus indexed',' − A'),e['feature'],fmt(float(e['median_difference'])),fmt(float(e['cliffs_delta_negative_vs_indexed'])),fmt(float(e['median_difference_bootstrap95_low']))+' bis '+fmt(float(e['median_difference_bootstrap95_high']))])
text += [table(['Vergleich','Merkmal','Mediandifferenz','Cliff δ','Exploratives 95%-Bootstrapintervall'],sel),'', 'Cliff δ beschreibt die Richtung/Stärke der Rangunterschiede, hier jeweils B oder C gegen A. Die Intervalle stammen aus 400 reproduzierbaren Resamples der Mediandifferenz; sie sind explorative Unsicherheitsangaben, keine bestätigenden Tests oder Korrektur für die vielen untersuchten Merkmale. Gemeinsame Templates und Themen erzeugen Abhängigkeiten, die diese einfachen Intervalle nicht modellieren. Alle Typ-/Cluster-Effektgrößen, Gruppengrößen, Quartile und relativen Mediandifferenzen stehen in den beigefügten CSV/JSON-Dateien.','', 'Für Alter zeigt B nahezu keinen Unterschied (δ etwa −0,034), C einen starken (δ etwa −0,927). Wiederholung ist bei Produkten in allen drei Gruppen häufig; der globale Unterschied wird teilweise durch den Mix von Produkttypen und Ratgebern bestimmt. Kein komplexes multivariables Modell wurde erzwungen: viele Typ-/Clusterzellen sind klein oder enthalten nur eine Statusgruppe; Merkmale sind stark korreliert und das Google-Urteil ist zeitlich nicht mit dem Textstand synchron.','', '## Verlinkung und technische Kontrollvariablen','', 'Die Matrix unterscheidet alle eingehenden Quellseiten, strukturell kontextuelle Links in Absatz/Liste/Tabelle sowie Navigation/automatische Module. Breadcrumbs, globale Navigation und erkannte Related-/Next-Steps-/Journey-Listen werden nicht als redaktioneller Kontext gezählt. Inline-Autolinks sind aus dem finalen HTML nicht in jedem Fall von manuell gesetzten Links unterscheidbar; deshalb „strukturell kontextuell“, nicht „ausschließlich manuell redaktionell“. Hubtiefe wird aus dem gerenderten Graphen berechnet; ohne passenden Themenhub bleibt sie unbekannt. Der ausgewiesene Graph-PageRank ist nur ein lokales Strukturmaß.','', 'Alle 259 aktuellen Canonicals haben im wiederverwendeten Liveaudit HTTP 200; Canonicals, Sitemap, indexierbare SSR-Hauptinhalte und strukturierte Daten sind als technische Kontrollen erfasst. Daraus wird kein Indexierungsstatus abgeleitet. Frühere 35.3B-Redirectfehler bleiben separate historische Befunde. Die Kohorte enthält 23 Migrations-/Konsolidierungsziele, davon 17 indexiert; das Ergebnis aus 35.3B wird nicht als neue Discovery-Diagnose ausgegeben.','', '## Entscheidungsvorlage – zwölf Antworten','', '1. **Stärkste Unterschiede:** erste belegte Git-Existenz, Seitentyp-/Clustermix und Kontextzugänge aus indexierten Quellen unterscheiden besonders die gefundenen Seiten. Für B fehlt eine ähnlich starke allgemeine Trennregel.','2. **Innerhalb gleicher Typen:** Bei Produkten schrumpfen Wort-/Quellen-/Linkunterschiede stark. Gecrawlte Ratgeber bleiben in vergleichbaren Clustern länger; fehlende Textmenge erklärt diese Fälle nicht.','3. **Alter oder Links:** C ist jünger und hat häufiger keine Kontextquelle aus A. Das ist mit Discovery vereinbar, keine abgeschlossene Erklärung; 13 gefundene Seiten sind ebenfalls alt. Bei B und A ist das Git-Alter praktisch gleich.','4. **Austauschbarkeit:** Gemeinsame Standardpassagen sind belegt; nach deren Entfernung gibt es keinen flächendeckenden Nachweis nahezu identischer Texte. Einzelne ähnliche Intents/Produktvarianten brauchen manuelle Abgrenzung. Niedriger lexikalischer Kosinus beweist keine Eigenständigkeit.','5. **Konkrete Lücken:** Produktseiten brauchen teils belastbarere Modell-/Betriebsgrenzen; Ratgeber teils passende technische Quellen und präzisere Folgerungen aus bestehenden Rechnungen. Das sind belegte Einzelfälle, keine Rangfolge einer gesamten Seitengattung.','6. **Indexierte Gegenbeispiele:** Eversweet 5 Mini, Dockstream RFID und Cat Mate C300 besitzen ebenfalls kurze bzw. allgemeine Erfahrungseinordnungen. Hersteller-/Vergleichsmodule wiederholen sich auch auf indexierten Seiten. Siehe Qualitätsevidenz.','7. **Ungeeignete Alleinindikatoren:** Wortzahl, Quellenanzahl, FAQ-/Überschriftenzahl, einheitliches Design, gemeinsame technische Begriffe, Produktnamen und fehlende eigene Praxistests. KI-Verwendung wurde nicht als Qualitätsfehler oder Abwertungsnachweis behandelt.','8. **Zehn verbesserte Seiten:** fünf Produkte und fünf Ratgeber aus der gecrawlten Gruppe; konkrete Liste und Nutzen in `experiment-selection.md`/`experiment-changes.md`. Auswahl vor Bearbeitung, kein Nachziehen nach Ergebnissen.','9. **Kontrollvergleichbarkeit:** Gleicher historischer Status, Typ/Cluster, mindestens 90 Git-Tage, keine Migration/35.4-Änderung; Matching nach Alter, Tiefe, Inlinks, Umfang und Wiederholungsanteil innerhalb praktischer Themenblöcke. Kleine Paare, unterschiedliche Geräteklassen und Leseraufgaben bleiben Störfaktoren.','10. **Stärkung der Qualitätshypothese:** Bei neuen Crawls, eigenen Google-Canonicals und stabiler Technik würden mehr Test- als Kontrollseiten nach 56 Tagen sowie ein über mehrere Messpunkte konsistenter Unterschied die konkrete Intervention stützen. Keine allgemeine Google-Qualitätsbewertung daraus ableiten.','11. **Gegenbefunde:** Gleich gute/bessere Kontrollen trotz erneuter Crawls und stabiler Canonicals schwächen den angenommenen Zusatznutzen für Indexierung. Keine Veränderung ohne neue Crawls ist dagegen kein aussagekräftiger Test der Textqualität.','12. **Spätere Maßnahmen:** Erst nach vollständiger 56-Tage-Beobachtung über Ausweitung, Zusammenlegung oder zusätzliche Quellenarbeit entscheiden. Technische echte Fehler bleiben sofort gesondert behebbar. Keine automatischen Indexierungsanträge und keine pauschale weitere Seitenbearbeitung.','', 'Aktuell ist nur die Vorbereitung abgeschlossen. GSC-Zugang ist nicht eingerichtet; die aktuelle Vor-Release-Messung der 20 URLs muss manuell ergänzt werden. Kein Release und keine Recoverywirkung werden behauptet.']
(P/'indexation-gap-analysis.md').write_text('\n'.join(text))
